import fs from "fs";
import path from "path";
import formidable from "formidable";

export const config = {
  api: { bodyParser: false },
};

export async function POST(req) {
  return new Promise((resolve) => {
    const uploadDir = path.join(process.cwd(), "public/uploads");

    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }

    const form = formidable({
      uploadDir,
      keepExtensions: true,
    });

    form.parse(req, (err, fields, files) => {
      if (err) {
        console.error("Error formidable:", err);
        return resolve(
          Response.json({ error: "Error subiendo archivo" }, { status: 500 })
        );
      }

      const file = files.photo || files.file;
      if (!file) {
        return resolve(
          Response.json({ error: "No vino archivo" }, { status: 400 })
        );
      }

      const fileName = path.basename(file.filepath);
      const finalPath = path.join(uploadDir, fileName);

      fs.renameSync(file.filepath, finalPath);

      return resolve(
        Response.json(
          { success: true, file: `/uploads/${fileName}` },
          { status: 200 }
        )
      );
    });
  });
}
